using System;
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");
var p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"  Deserialized: {p}");

Console.WriteLine();

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    Use a source-gen-only resolver that only knows about "Person"
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyContext()
};

bool found = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

bool found2 = limitedOptions.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Order):  found={found2}, info={info2?.ToString() ?? "null"}");

// --- Types ---------------------------------------------------------------
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A custom resolver that only resolves Person
class PersonOnlyContext : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null;  // signals "I don't know this type"
    }
}
EOF

